const event = $json.event ?? $json;
const raw = String(event.text ?? '').replace(/^\[SIM:[^\]]+\]\s*/, '').trim();
const sourceEventId = String(event.client_msg_id ?? event.event_id ?? `${event.channel ?? 'unknown'}:${event.ts ?? Date.now()}`);
return [{ json: { source_event_id: sourceEventId, text: raw, is_valid: raw.length >= 10, received_at: event.ts ? new Date(Number(String(event.ts).split('.')[0]) * 1000).toISOString() : new Date().toISOString(), source: 'slack', workflow_version: 'v0', original_event: event } }];

const input = $('Normalize and validate input').item.json;
const values = $json.embedding?.values;
if (!Array.isArray(values) || values.length !== 768 || !values.every(Number.isFinite)) { throw new Error('Invalid Gemini embedding: expected 768 numeric values'); }
return [{ json: { ...input, embedding_model: 'gemini-embedding-001', embedding_vector: `[${values.join(',')}]` } }];
